/*
 * prog17_whitespace_trim.c
 *
 * Re‑implementation of the original program whose behaviour was recovered
 * from the obfuscated binary.  The program:
 *
 *   • Takes the first command‑line argument (argv[1]).
 *   • If no argument is supplied, prints "EMPTY".
 *   • Considers only the first 1024 characters of the argument.
 *   • Trims leading and trailing whitespace.
 *   • Collapses any run of whitespace characters (space, '\t', '\n',
 *     '\r', '\v', '\f') to a single space character.
 *   • If the resulting string is empty, prints "EMPTY".
 *   • Otherwise prints the processed string followed by a newline
 *     (using `puts`, exactly as the original binary does).
 *
 * The implementation follows the logic observed in the decompiled
 * state‑machine of the original binary, but is written in clear C.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT 1024   /* limit imposed by the original program */

int main(int argc, char **argv)
{
    /* No argument → "EMPTY" */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    const char *src = argv[1];
    size_t src_len = strlen(src);
    if (src_len > MAX_INPUT)          /* truncate to 1024 bytes */
        src_len = MAX_INPUT;

    char out[MAX_INPUT + 1];          /* output buffer (always fits) */
    size_t out_idx = 0;

    int in_leading_ws = 1;   /* still skipping leading whitespace */
    int pending_space = 0;   /* a space should be inserted before the next word */

    for (size_t i = 0; i < src_len; ++i) {
        unsigned char ch = (unsigned char)src[i];

        if (isspace(ch)) {
            /* Remember that we have seen whitespace after a word.
               Leading whitespace is ignored because `in_leading_ws` is still true. */
            if (!in_leading_ws)
                pending_space = 1;
        } else {
            /* Insert a single space if we just left a run of whitespace. */
            if (pending_space) {
                out[out_idx++] = ' ';
                pending_space = 0;
            }
            out[out_idx++] = ch;
            in_leading_ws = 0;   /* we are now inside a word */
        }
    }

    out[out_idx] = '\0';

    if (out_idx == 0)          /* nothing left after trimming */
        puts("EMPTY");
    else
        puts(out);             /* prints the trimmed, collapsed string */

    return 0;
}
